P=Path(__file__).parent; ROOT=P.parent.parent
S=json.loads((P/'snapshot.json').read_text()); D=json.loads((P/'source_tables.json').read_text()); E=D['phrases_and_examples']; G={g['id']:g for g in S}
EX=json.loads((P/'examples.json').read_text()); flags=[]
def meanings(term):
 g=G.get(term.lower());return '; '.join((u['type'] or 'No word-type label')+': '+u['meaning'] for u in g['uses']) if g else 'No standalone dictionary entry or registered variant found.'
def evidence(indices):
 result=[]
 for i in indices:
  e=E[i]; shown=next((x for x in EX if x['celan']==e['celan_text'] and x['english']==e['translation']),None)
  if not shown:continue
  result.append({'source_id':e['entry_id'],'celan':e['celan_text'],'english':e['translation'],'shown_on':shown['visible_on'],'available_on':shown['headwords']})
 return result
def add(category,title,terms,why,decision,indices=(),certainty='Needs a decision',current=None):
 f={'id':f'F{len(flags)+1:03}','category':category,'title':title,'words':terms,'certainty':certainty,'what_the_app_says':current or {t:meanings(t) for t in terms},'why_flagged':why,'decision':decision,'examples':evidence(indices),'status':'Flagged only — no language change applied'}
 flags.append(f);return f
def selected(term,pattern):
 return [i for i,e in enumerate(E) if re.search(r'(?<![A-Za-z])'+re.escape(term)+r'(?![A-Za-z])',e['celan_text'],re.I) and re.search(pattern,e['translation'],re.I)]
